#!/usr/bin/env node
/**
 * Write the JS fallback launcher (`dist/phronia.mjs`).
 *
 * The CLI reads platform template files from disk, so a standalone single
 * file needs asset embedding (part of the deferred binary work). The npm
 * fallback is therefore a launcher over the installed `@phronia/cli` dist.
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const out = resolve(root, "dist/phronia.mjs");
const cli = resolve(root, "../cli/dist/cli/index.js");

mkdirSync(dirname(out), { recursive: true });
writeFileSync(
  out,
  `#!/usr/bin/env node
// Generated by packages/runtime/scripts/build-js-bundle.mjs
import { existsSync } from "node:fs";
import { pathToFileURL } from "node:url";
const cli = ${JSON.stringify(cli)};
if (!existsSync(cli)) {
  console.error("phronia: @phronia/cli dist is missing; run pnpm build first");
  process.exit(1);
}
await import(pathToFileURL(cli).href);
`,
  "utf8",
);
console.log(`wrote ${out}`);
